//! JSON API of the `tags` resource, generated by
//! `forge generate resource` (and `forge generate scaffold`). Handlers stay
//! thin: authorize, decode the request, call [`TagService`], answer
//! JSON.
//!
//! | Method | Path | Action | Permission |
//! | --- | --- | --- | --- |
//! | `GET` | `/v1/tags?cursor=ID` | list, in creation order, `PAGE_SIZE` per page | `tags:read` |
//! | `POST` | `/v1/tags` | create: `201` with `Location` | `tags:write` |
//! | `GET` | `/v1/tags/{id}` | show | `tags:read` |
//! | `PATCH` | `/v1/tags/{id}` | change the members sent, with the `version` read | `tags:write` |
//! | `DELETE` | `/v1/tags/{id}?version=N` | delete the version read: `204` | `tags:write` |
//!
//! A stale `version` answers `409`, an invalid value `422` with a message
//! per member in `metadata`, an unknown `{id}` `404`. `PATCH` changes only
//! the members it names; `null` clears an optional one. Every route is
//! described in the OpenAPI document (`GET /openapi.json`, `forge openapi`).

use std::future::Future;
use std::sync::Arc;

use forge::ComposeError;
use forge::core::{ErrorCategory, ForgeError, Version};
use forge::http::{HeaderValue, Method, Request, Response, Router, StatusCode, header};
use forge::openapi::{OpenApiSchema, Operation, Param, describe};
use forge::security::Permission;
use forge::web::Patch;
use serde::{Deserialize, Serialize};

use crate::adapters::http::api_access::ApiGlobalAccess;
use crate::application::use_cases::tags::{
    READ_PERMISSION, TagError, TagService, WRITE_PERMISSION,
};
use crate::domain::entities::tag::{Tag, TagAttributes, TagId};

/// The collection's path.
pub const COLLECTION_PATH: &str = "/v1/tags";

/// A tag as the API answers it.
#[derive(Debug, Serialize, OpenApiSchema)]
pub struct TagJson {
    /// The tag's UUIDv7.
    pub id: TagId,
    pub label: String,
    pub active: Option<bool>,
    /// The optimistic-locking version: `PATCH` and `DELETE` send it back.
    pub version: i64,
}

impl From<&Tag> for TagJson {
    fn from(tag: &Tag) -> Self {
        let TagAttributes { label, active } = tag.attributes().clone();
        Self {
            id: tag.id(),
            label,
            active,
            version: tag.version().get(),
        }
    }
}

/// One page of tags.
#[derive(Debug, Serialize, OpenApiSchema)]
pub struct TagList {
    pub items: Vec<TagJson>,
    /// The `cursor` of the next page; `null` on the last one.
    pub next_cursor: Option<TagId>,
}

/// The body of `POST`: every required member.
#[derive(Debug, Deserialize, OpenApiSchema)]
pub struct NewTag {
    pub label: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub active: Option<bool>,
}

impl From<NewTag> for TagAttributes {
    fn from(body: NewTag) -> Self {
        let NewTag { label, active } = body;
        Self { label, active }
    }
}

/// The body of `PATCH`: the version read and the members to change. A member
/// left out stays as it is; `null` clears an optional one.
#[derive(Debug, Deserialize, OpenApiSchema)]
pub struct TagChanges {
    /// The version the client last read.
    pub version: i64,
    #[serde(default, skip_serializing_if = "Patch::is_absent")]
    pub label: Patch<String>,
    #[serde(default, skip_serializing_if = "Patch::is_absent")]
    pub active: Patch<bool>,
}

impl TagChanges {
    /// Applies the members sent to `attributes`; `null` for a required
    /// member is refused.
    fn apply(self, attributes: &mut TagAttributes) -> Result<(), ForgeError> {
        match self.label {
            Patch::Absent => {}
            Patch::Null => return Err(not_null("label")),
            Patch::Value(value) => attributes.label = value,
        }
        match self.active {
            Patch::Absent => {}
            Patch::Null => attributes.active = None,
            Patch::Value(value) => attributes.active = Some(value),
        }
        Ok(())
    }
}

/// The query of `GET /v1/tags`.
#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct ListQuery {
    cursor: Option<TagId>,
}

/// The query of `DELETE`: the version the client last read.
#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct DeleteQuery {
    version: i64,
}

/// What every handler shares.
struct TagApi {
    service: TagService,
    access: Arc<dyn ApiGlobalAccess>,
    read: Permission,
    write: Permission,
}

/// Registers the routes. `access` decides who may call them (see
/// `crate::adapters::http::api_access`); nothing is served before it agrees.
pub fn routes(
    router: &mut Router,
    service: TagService,
    access: Arc<dyn ApiGlobalAccess>,
) -> Result<(), ComposeError> {
    let state = Arc::new(TagApi {
        service,
        access,
        read: Permission::new(READ_PERMISSION).map_err(ComposeError::other)?,
        write: Permission::new(WRITE_PERMISSION).map_err(ComposeError::other)?,
    });
    let member = format!("{COLLECTION_PATH}/{{id}}");
    let id = || Param::path::<TagId>("id").doc("The tag's ID.");
    route(
        router,
        &state,
        Method::GET,
        COLLECTION_PATH,
        list,
        operation("listTags", "List tags, in creation order", READ_PERMISSION)
            .param(
                Param::query::<Option<TagId>>("cursor")
                    .doc("The next_cursor of the previous page."),
            )
            .json::<TagList>(200)
            .errors([422]),
    )?;
    route(
        router,
        &state,
        Method::POST,
        COLLECTION_PATH,
        create,
        operation("createTag", "Create a tag", WRITE_PERMISSION)
            .request::<NewTag>()
            .response(forge::openapi::Response::json::<TagJson>(201).header("Location")),
    )?;
    route(
        router,
        &state,
        Method::GET,
        &member,
        show,
        operation("getTag", "Get a tag", READ_PERMISSION)
            .param(id())
            .json::<TagJson>(200)
            .errors([400, 404]),
    )?;
    route(
        router,
        &state,
        Method::PATCH,
        &member,
        update,
        operation(
            "updateTag",
            "Change some members of a tag",
            WRITE_PERMISSION,
        )
        .param(id())
        .request::<TagChanges>()
        .json::<TagJson>(200)
        .errors([400, 404, 409]),
    )?;
    route(
        router,
        &state,
        Method::DELETE,
        &member,
        destroy,
        operation("deleteTag", "Delete a tag", WRITE_PERMISSION)
            .param(id())
            .param(
                Param::query::<i64>("version")
                    .required()
                    .doc("The version the client last read."),
            )
            .response(forge::openapi::Response::empty(204))
            .errors([400, 404, 409, 422]),
    )?;
    Ok(())
}

/// The description every route shares: bearer authentication, the
/// permission and the access policy's `503`.
fn operation(id: &str, summary: &str, permission: &str) -> Operation {
    Operation::new()
        .id(id)
        .summary(summary)
        .tag("tags")
        .bearer()
        .permission(permission)
        .errors([503])
}

fn route<H, F>(
    router: &mut Router,
    state: &Arc<TagApi>,
    method: Method,
    path: &str,
    handler: H,
    operation: Operation,
) -> Result<(), ComposeError>
where
    H: Fn(Arc<TagApi>, Request) -> F + Send + Sync + 'static,
    F: Future<Output = Response> + Send + 'static,
{
    let state = Arc::clone(state);
    router.route(
        method,
        path,
        describe(
            move |request: Request| handler(Arc::clone(&state), request),
            operation,
        ),
    )?;
    Ok(())
}

async fn list(state: Arc<TagApi>, request: Request) -> Response {
    if let Err(denied) = state.access.authorize(&request, &state.read).await {
        return forge::web::bearer_refusal(denied);
    }
    let query: ListQuery = match forge::web::decode_query(&request) {
        Ok(query) => query,
        Err(failure) => return forge::web::error(&failure),
    };
    match state.service.list(query.cursor).await {
        Ok(page) => forge::web::json(
            StatusCode::OK,
            &TagList {
                items: page.tags.iter().map(TagJson::from).collect(),
                next_cursor: page.next,
            },
        ),
        Err(error) => failure(error),
    }
}

async fn create(state: Arc<TagApi>, request: Request) -> Response {
    if let Err(denied) = state.access.authorize(&request, &state.write).await {
        return forge::web::bearer_refusal(denied);
    }
    let body: NewTag = match forge::web::decode_json_strict(&request) {
        Ok(body) => body,
        Err(failure) => return forge::web::error(&failure),
    };
    match state.service.create(body.into()).await {
        Ok(tag) => {
            let mut response = forge::web::json(StatusCode::CREATED, &TagJson::from(&tag));
            if let Ok(location) = HeaderValue::from_str(&format!("{COLLECTION_PATH}/{}", tag.id()))
            {
                response.headers_mut().insert(header::LOCATION, location);
            }
            response
        }
        Err(error) => failure(error),
    }
}

async fn show(state: Arc<TagApi>, request: Request) -> Response {
    if let Err(denied) = state.access.authorize(&request, &state.read).await {
        return forge::web::bearer_refusal(denied);
    }
    let Some(id) = path_id(&request) else {
        return invalid_id();
    };
    match state.service.find(id).await {
        Ok(tag) => forge::web::json(StatusCode::OK, &TagJson::from(&tag)),
        Err(error) => failure(error),
    }
}

async fn update(state: Arc<TagApi>, request: Request) -> Response {
    if let Err(denied) = state.access.authorize(&request, &state.write).await {
        return forge::web::bearer_refusal(denied);
    }
    let Some(id) = path_id(&request) else {
        return invalid_id();
    };
    let changes: TagChanges = match forge::web::decode_json_strict(&request) {
        Ok(changes) => changes,
        Err(failure) => return forge::web::error(&failure),
    };
    let expected = match Version::new(changes.version) {
        Ok(expected) => expected,
        Err(failure) => return forge::web::error(&failure),
    };
    // The stored attributes with the members sent; the update itself checks
    // that the version read is still the stored one.
    let mut attributes = match state.service.find(id).await {
        Ok(tag) => tag.attributes().clone(),
        Err(error) => return failure(error),
    };
    if let Err(failure) = changes.apply(&mut attributes) {
        return forge::web::error(&failure);
    }
    match state.service.update(id, expected, attributes).await {
        Ok(tag) => forge::web::json(StatusCode::OK, &TagJson::from(&tag)),
        Err(error) => failure(error),
    }
}

async fn destroy(state: Arc<TagApi>, request: Request) -> Response {
    if let Err(denied) = state.access.authorize(&request, &state.write).await {
        return forge::web::bearer_refusal(denied);
    }
    let Some(id) = path_id(&request) else {
        return invalid_id();
    };
    let expected = match forge::web::decode_query::<DeleteQuery>(&request)
        .and_then(|query| Version::new(query.version))
    {
        Ok(expected) => expected,
        Err(failure) => return forge::web::error(&failure),
    };
    match state.service.delete(id, expected).await {
        Ok(()) => Response::empty(StatusCode::NO_CONTENT),
        Err(error) => failure(error),
    }
}

/// The route's `{id}`, when it is a UUIDv7.
fn path_id(request: &Request) -> Option<TagId> {
    request.path_param_as("id").ok()
}

/// `400 invalid_id`: the `{id}` is not a UUIDv7.
fn invalid_id() -> Response {
    let failure = ForgeError::new(
        ErrorCategory::Validation,
        "invalid_id",
        "the tag ID is not a UUIDv7",
    );
    forge::web::json(StatusCode::BAD_REQUEST, &failure.report())
}

/// The JSON answer to a failed use case.
fn failure(error: TagError) -> Response {
    match error {
        TagError::Invalid(violations) => {
            let mut failure = ForgeError::new(
                ErrorCategory::Validation,
                "validation_failed",
                "the tag is invalid",
            );
            for (field, violation) in violations.iter() {
                failure = failure.with_metadata(field.name(), violation.to_string());
            }
            forge::web::error(&failure)
        }
        TagError::NotFound => forge::web::error(&ForgeError::new(
            ErrorCategory::NotFound,
            "tag_not_found",
            "tag not found",
        )),
        TagError::Conflict => forge::web::error(&ForgeError::new(
            ErrorCategory::Conflict,
            "tag_conflict",
            "the tag was changed by someone else",
        )),
        // Logged with its cause chain; the client sees a generic report.
        TagError::Store(error) => forge::web::error(
            &ForgeError::new(
                ErrorCategory::Infrastructure,
                "tag_storage_failed",
                "service temporarily unavailable",
            )
            .with_source(error),
        ),
    }
}

/// `null` for a member that cannot be empty.
fn not_null(member: &str) -> ForgeError {
    ForgeError::new(
        ErrorCategory::Validation,
        "validation_failed",
        "the tag is invalid",
    )
    .with_metadata(member, "can't be null")
}
